// ❌ OLD: Monkey-patching core modules to add telemetry. Replacing
// http.request globally breaks if another library also patches it,
// breaks when Node's internals change, and doesn't observe internal
// events (DNS, sockets, worker threads) that the patch can't reach.
const http = require('node:http');
const origRequest = http.request;

http.request = (...args) => {
  const start = process.hrtime.bigint();
  const req = origRequest(...args); // ❌ OLD: fragile wrapper
  req.on('response', () => {
    logDuration(process.hrtime.bigint() - start);
  });
  return req;
};

// Problems: global mutation, version coupling, other patches conflict.

const dc = require('node:diagnostics_channel');

// ✅ NEW: Subscribe to Node's built-in channels — no patching, no
// global mutation, works across versions.
const startChannel = dc.channel('http.client.request.start');
const finishChannel = dc.channel('http.client.request.finish');

const starts = new WeakMap();

startChannel.subscribe((message) => {
  // ✅ NEW: message contains the request/socket context
  starts.set(message.request, process.hrtime.bigint());
});

finishChannel.subscribe((message) => {
  const start = starts.get(message.request);
  if (start) {
    logDuration(message.request, process.hrtime.bigint() - start);
  }
});

